messages.content:
Write a single self-contained HTML file with a 3D animation using three.js. three.js r160 is available as an ES module at './three.module.js' -- import it with:
  import * as THREE from './three.module.js';
Scene: two cars race on a straight track toward a visible finish line. One car is bright RED, the other bright BLUE. The blue car leads early, then the red car accelerates, overtakes mid-race, and wins. After the red car crosses the finish line the race resets and loops forever. Both cars must be clearly visible and large enough to follow throughout (fill a meaningful part of the frame). Simple ground and sky, camera keeps both cars in view. No external assets besides the three.js import. Output ONLY the HTML in one code block.

response.text:
```html
<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <title>Three.js Car Race</title>
    <style>
        body { margin: 0; overflow: hidden; background: #000; }
        canvas { display: block; }
    </style>
</head>
<body>
<script type="module">
    import * as THREE from './three.module.js';

    // --- Configuration ---
    const TRACK_LENGTH = 100;
    const START_Z = 0;
    const FINISH_Z = -TRACK_LENGTH;
    const LANE_LEFT_X = -2.5;
    const LANE_RIGHT_X = 2.5;
    const CAR_SPEED_BASE = 0.3;
    const CAR_SPEED_BOOST = 0.55;

    // --- Scene Setup ---
    const scene = new THREE.Scene();
    scene.background = new THREE.Color(0x87CEEB); // Sky blue
    scene.fog = new THREE.Fog(0x87CEEB, 20, 90);

    const camera = new THREE.PerspectiveCamera(60, window.innerWidth / window.innerHeight, 0.1, 200);
    const renderer = new THREE.WebGLRenderer({ antialias: true });
    renderer.setSize(window.innerWidth, window.innerHeight);
    renderer.shadowMap.enabled = true;
    renderer.shadowMap.type = THREE.PCFSoftShadowMap;
    document.body.appendChild(renderer.domElement);

    // --- Lighting ---
    const ambientLight = new THREE.AmbientLight(0xffffff, 0.6);
    scene.add(ambientLight);

    const dirLight = new THREE.DirectionalLight(0xffffff, 1);
    dirLight.position.set(10, 20, 10);
    dirLight.castShadow = true;
    dirLight.shadow.mapSize.width = 1024;
    dirLight.shadow.mapSize.height = 1024;
    dirLight.shadow.camera.near = 0.5;
    dirLight.shadow.camera.far = 100;
    dirLight.shadow.camera.left = -15;
    dirLight.shadow.camera.right = 15;
    dirLight.shadow.camera.top = 15;
    dirLight.shadow.camera.bottom = -15;
    scene.add(dirLight);

    // --- Environment ---
    // Ground
    const groundGeo = new THREE.PlaneGeometry(200, 200);
    const groundMat = new THREE.MeshStandardMaterial({ color: 0x3a5f0b, roughness: 0.8 });
    const ground = new THREE.Mesh(groundGeo, groundMat);
    ground.rotation.x = -Math.PI / 2;
    ground.position.y = -0.1;
    ground.receiveShadow = true;
    scene.add(ground);

    // Track
    const trackGeo = new THREE.PlaneGeometry(10, TRACK_LENGTH + 20);
    const trackMat = new THREE.MeshStandardMaterial({ color: 0x555555 });
    const track = new THREE.Mesh(trackGeo, trackMat);
    track.rotation.x = -Math.PI / 2;
    track.position.z = -TRACK_LENGTH / 2;
    track.receiveShadow = true;
    scene.add(track);

    // Finish Line
    const finishGeo = new THREE.PlaneGeometry(10, 2);
    const finishMat = new THREE.MeshStandardMaterial({ color: 0xffffff });
    const finishLine = new THREE.Mesh(finishGeo, finishMat);
    finishLine.rotation.x = -Math.PI / 2;
    finishLine.position.z = FINISH_Z;
    finishLine.position.y = 0.02;
    scene.add(finishLine);

    // Finish Line Posts
    const postGeo = new THREE.BoxGeometry(0.5, 4, 0.5);
    const postMat = new THREE.MeshStandardMaterial({ color: 0xffffff });
    const postL = new THREE.Mesh(postGeo, postMat);
    postL.position.set(-5, 2, FINISH_Z);
    postL.castShadow = true;
    scene.add(postL);
    const postR = new THREE.Mesh(postGeo, postMat);
    postR.position.set(5, 2, FINISH_Z);
    postR.castShadow = true;
    scene.add(postR);

    // --- Car Builder ---
    function createCar(colorHex) {
        const carGroup = new THREE.Group();

        // Chassis
        const chassisGeo = new THREE.BoxGeometry(2, 1, 4);
        const chassisMat = new THREE.MeshStandardMaterial({ color: colorHex, roughness: 0.3, metalness: 0.4 });
        const chassis = new THREE.Mesh(chassisGeo, chassisMat);
        chassis.position.y = 1;
        chassis.castShadow = true;
        carGroup.add(chassis);

        // Cabin
        const cabinGeo = new THREE.BoxGeometry(1.8, 0.8, 2);
        const cabinMat = new THREE.MeshStandardMaterial({ color: 0x333333, roughness: 0.1 });
        const cabin = new THREE.Mesh(cabinGeo, cabinMat);
        cabin.position.y = 1.9;
        cabin.position.z = -0.5;
        cabin.castShadow = true;
        carGroup.add(cabin);

        // Wheels
        const wheelGeo = new THREE.CylinderGeometry(0.4, 0.4, 0.3, 16);
        const wheelMat = new THREE.MeshStandardMaterial({ color: 0x111111 });

        const wheelPositions = [
            [-1.1, 0.4, 1.2], [1.1, 0.4, 1.2],
            [-1.1, 0.4, -1.2], [1.1, 0.4, -1.2]
        ];

        wheelPositions.forEach(pos => {
            const wheel = new THREE.Mesh(wheelGeo, wheelMat);
            wheel.rotation.z = Math.PI / 2;
            wheel.position.set(...pos);
            wheel.castShadow = true;
            carGroup.add(wheel);
        });

        return carGroup;
    }

    // --- Cars ---
    const redCar = createCar(0xff0000);
    redCar.position.set(LANE_LEFT_X, 0, START_Z);
    scene.add(redCar);

    const blueCar = createCar(0x0000ff);
    blueCar.position.set(LANE_RIGHT_X, 0, START_Z);
    scene.add(blueCar);

    // --- State ---
    let time = 0;
    const resetPoint = { z: START_Z };

    // --- Animation Loop ---
    function animate() {
        requestAnimationFrame(animate);

        // Race Logic: 0 to 1 represents the race duration
        // Blue leads for first half, Red accelerates and overtakes in second half
        const speed = 0.003; // Global time increment
        time += speed;

        // Logic to determine positions
        // Blue car: Linear progress
        // Red car: Linear initially, then accelerates

        let blueProgress = time * 40; // Base speed multiplier
        let redProgress = time * 40;

        // Blue leads early (0 - 0.5)
        // Red catches up at 0.5 and overtakes

        // Simple physics simulation
        // Blue: constant speed
        // Red: starts same speed, accelerates after halfway

        const raceDuration = 1.0; // Time units
        const raceTotalDistance = TRACK_LENGTH;

        // Calculate positions based on a "race curve"
        // Blue: linear
        const blueSpeed = 60; 
        const bluePos = blueSpeed * time;

        // Red: linear then acceleration
        // Red starts slightly behind or equal, then zooms past
        const redBaseSpeed = 55;
        const redBoostSpeed = 85;
        const redBoostStart = 12; // Time unit when red starts boosting

        let redPos;
        if (time < redBoostStart) {
            redPos = redBaseSpeed * time;
        } else {
            // Red has covered base distance + boosted distance
            const distanceAtBoost = redBaseSpeed * redBoostStart;
            const timeAfterBoost = time - redBoostStart;
            redPos = distanceAtBoost + (redBoostSpeed * timeAfterBoost);
        }

        // Reset condition: Red crosses finish line
        if (redPos >= FINISH_Z) {
            time = 0;
            // Visual reset (cars snap back)
        }

        // Update Positions
        // We map our calculated "speed*time" to actual Z coordinates
        // Scale factor to ensure they reach the finish line at the right time
        const scale = 0.4; 

        blueCar.position.z = START_Z - (Math.min(bluePos * scale, FINISH_Z));
        redCar.position.z = START_Z - (Math.min(redPos * scale, FINISH_Z));

        // Add slight bouncing for realism
        blueCar.position.y = Math.sin(time * 20) * 0.05;
        redCar.position.y = Math.sin(time * 20) * 0.05;

        // Rotate wheels
        const wheelRotation = time * 10;
        redCar.children.forEach(child => {
            if (child.geometry.type === 'CylinderGeometry') {
                child.rotation.x = wheelRotation;
            }
        });
        blueCar.children.forEach(child => {
            if (child.geometry.type === 'CylinderGeometry') {
                child.rotation.x = wheelRotation;
            }
        });

        // Camera: Follow the leader (Red car) but keep both in view
        // Camera position: behind and above the leading car
        const leadCar = redCar.position.z < blueCar.position.z ? redCar : blueCar;

        const camX = 0;
        const camY = 12;
        const camZ = leadCar.position.z + 15;

        camera.position.set(camX, camY, camZ);
        camera.lookAt(leadCar.position.x, 0, leadCar.position.z - 10);

        renderer.render(scene, camera);
    }

    // Handle window resize
    window.addEventListener('resize', () => {
        camera.aspect = window.innerWidth / window.innerHeight;
        camera.updateProjectionMatrix();
        renderer.setSize(window.innerWidth, window.innerHeight);
    });

    animate();
</script>
</body>
</html>
```
